from pathlib import Path

def plan_archive(root: str, names: list[str]) -> list[Path]:
    if not names or root in ('', '.'):
        return []

    root_path = Path(root)
    if root_path.is_absolute() or (root_path.drive and root_path.root) or '..' in root_path.parts:
        return []

    resolved_paths = []
    for name in names:
        path = root_path / name
        if path.is_absolute() or (path.drive and path.root) or '..' in path.parts or path.symlink_to().exists():
            return []

        if any(path.resolve() == existing.resolve() for existing in resolved_paths):
            return []

        resolved_paths.append(path)

    return [path.resolve() for path in resolved_paths]
