def deploy_change(change, precheck, stage, validate, finalize, revert):
    try:
        if not precheck():
            return False
        try:
            stage_result = stage()
            validate_result = validate(stage_result)
            if not validate_result:
                raise ValueError("Validation failed")
        finally:
            if not (validate_result or not any([stage_result.raise_exception(), finalize().raise_exception()])):
                revert()
    except Exception as e:
        print(f"An error occurred: {e}")
    else:
        return finalize()
