import copy

def make_operation_record(action: str, request: dict, ok: bool, result: dict) -> dict:
    if not action or not isinstance(request, dict) or not isinstance(ok, bool) or not isinstance(result, dict):
        raise ValueError("Invalid input types")

    record = {
        "action": action,
        "request": copy.deepcopy(request),
        "outcome": {"ok": ok, "result": copy.deepcopy(result)}
    }
    return record
